// ReverseIntSlice reverses a slice of integers in place.
// It modifies the original slice directly and returns nothing.
func ReverseIntSlice(slice []int) {
	// Initialize two pointers: 'left' at the start and 'right' at the end.
	left := 0
	right := len(slice) - 1

	// Continue swapping elements until the pointers meet or cross each other.
	for left < right {
		// 1. Swap the elements at the left and right indices
		// We need a temporary variable to hold the value at the left index.
		temp := slice[left]
		slice[left] = slice[right]
		slice[right] = temp

		// 2. Move the pointers inward
		left++
		right--
	}
}

